    [Fact]
    public async Task GetProductsAsync_QWithoutMatch_ReturnsEmptyListWithZeroTotalCount()
    {
        var result = await _sut.GetProductsAsync(q: "kein-treffer-xyz");

        Assert.Empty(result.Items);
        Assert.Equal(0, result.TotalCount);
