  let subcategoriesApiMock: { getProperties: ReturnType<typeof vi.fn> };

  const categories: Category[] = [
    { id: 'K1', name: 'Elektronik', subcategories: [{ id: 'K1a', name: 'Kopfhörer' }] },
  ];

  beforeEach(async () => {
    productsApiMock = {
      getProducts: vi.fn(),
    };
